-- ── hand-written: grants and row-level security ─────────────────────────────────────────────────

REVOKE ALL ON public.stock_transfers, public.stock_transfer_lines, public.stock_adjustments, public.stock_adjustment_lines, public.stock_counts, public.stock_count_lines
  FROM anon, authenticated, service_role;
--> statement-breakpoint
-- A draft is written, changed and thrown away by the app. Its lines are added and removed,
-- never edited, except that a count line takes what was counted.
GRANT SELECT, INSERT, DELETE ON public.stock_transfers, public.stock_transfer_lines, public.stock_adjustments, public.stock_adjustment_lines, public.stock_counts, public.stock_count_lines
  TO app_runtime;
--> statement-breakpoint
-- What the app may change on a draft. Not the status, the number, who posted it or its
-- journal: only the posting functions below write those, so the app cannot mark a document
-- posted. Not an adjustment's kind, nor a count's warehouse, which its lines were written for.
GRANT UPDATE (transfer_date, from_warehouse_id, to_warehouse_id, note, updated_at, updated_by) ON public.stock_transfers TO app_runtime;
--> statement-breakpoint
GRANT UPDATE (adjustment_date, warehouse_id, reason, note, updated_at, updated_by) ON public.stock_adjustments TO app_runtime;
--> statement-breakpoint
GRANT UPDATE (count_date, note, updated_at, updated_by) ON public.stock_counts TO app_runtime;
--> statement-breakpoint
-- What the books held is written by the database itself; the app writes only what was counted.
GRANT UPDATE (counted_quantity) ON public.stock_count_lines TO app_runtime;
