-- A member limited to some branches sees only those branches' warehouses (the warehouses' own
-- policy, drizzle/0008_numbering.sql), and the policies below ask through it.
--
-- Transfers: read by the owner, whoever keeps or checks the books, and the warehouse, where
-- either warehouse is one the member sees, so the receiving branch sees what arrived. Written
-- by the owner, an accountant and the warehouse, and only between two warehouses the member
-- sees: a member of one branch cannot move another branch's stock.
CREATE POLICY stock_transfers_select ON public.stock_transfers FOR SELECT TO app_runtime
  USING (
    tenant_id = (SELECT app.tenant_id())
    AND (SELECT app.tenant_role()) IN ('owner', 'accountant', 'auditor', 'warehouse_manager')
    AND EXISTS (SELECT 1 FROM public.warehouses w WHERE w.tenant_id = stock_transfers.tenant_id AND w.id IN (stock_transfers.from_warehouse_id, stock_transfers.to_warehouse_id))
  );
--> statement-breakpoint
CREATE POLICY stock_transfers_insert ON public.stock_transfers FOR INSERT TO app_runtime
  WITH CHECK (
    tenant_id = (SELECT app.tenant_id())
    AND (SELECT app.tenant_role()) IN ('owner', 'accountant', 'warehouse_manager')
    AND status = 'draft'
    AND created_by = (SELECT app.current_user_id())
    AND updated_by = (SELECT app.current_user_id())
    AND EXISTS (SELECT 1 FROM public.warehouses w WHERE w.tenant_id = stock_transfers.tenant_id AND w.id = stock_transfers.from_warehouse_id)
    AND EXISTS (SELECT 1 FROM public.warehouses w WHERE w.tenant_id = stock_transfers.tenant_id AND w.id = stock_transfers.to_warehouse_id)
  );
--> statement-breakpoint
