-- Adjustments and opening stock change what the books say stock is worth, and their lines can
-- carry a cost. So they are read only by the owner and whoever keeps or checks the books, and
-- written only by the owner and an accountant (the founder's decision, 2026-11-14). The
-- warehouse reports a difference through a count.
CREATE POLICY stock_adjustments_select ON public.stock_adjustments FOR SELECT TO app_runtime
  USING (
    tenant_id = (SELECT app.tenant_id())
    AND (SELECT app.tenant_role()) IN ('owner', 'accountant', 'auditor')
    AND EXISTS (SELECT 1 FROM public.warehouses w WHERE w.tenant_id = stock_adjustments.tenant_id AND w.id = stock_adjustments.warehouse_id)
  );
--> statement-breakpoint
CREATE POLICY stock_adjustments_insert ON public.stock_adjustments FOR INSERT TO app_runtime
  WITH CHECK (
    tenant_id = (SELECT app.tenant_id())
    AND (SELECT app.tenant_role()) IN ('owner', 'accountant')
    AND status = 'draft'
    AND created_by = (SELECT app.current_user_id())
    AND updated_by = (SELECT app.current_user_id())
    AND EXISTS (SELECT 1 FROM public.warehouses w WHERE w.tenant_id = stock_adjustments.tenant_id AND w.id = stock_adjustments.warehouse_id)
  );
--> statement-breakpoint
CREATE POLICY stock_adjustments_update ON public.stock_adjustments FOR UPDATE TO app_runtime
  USING (
    tenant_id = (SELECT app.tenant_id())
    AND (SELECT app.tenant_role()) IN ('owner', 'accountant')
    AND status = 'draft'
    AND EXISTS (SELECT 1 FROM public.warehouses w WHERE w.tenant_id = stock_adjustments.tenant_id AND w.id = stock_adjustments.warehouse_id)
