-- ── hand-written: what may happen to a stock document ───────────────────────────────────────────
-- The same guard for the three kinds of document, whoever writes the row, the posting
-- functions included. A document starts as a draft. A posted one is never changed and only a
-- draft is removed. The times on a row are the database's own. Only a session signed in as
-- postgres itself (a migration, or the removal of a synthetic test company) is not held to
-- this. Who may write a draft, and which of its columns, is for the grants and policies above.
CREATE FUNCTION app.check_stock_document() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
BEGIN
  IF session_user = 'postgres' THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'DELETE' THEN
    IF OLD.tenant_id IS DISTINCT FROM app.tenant_id() THEN
      RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF OLD.status <> 'draft' THEN
      RAISE EXCEPTION 'a finished or posted stock document is never removed' USING ERRCODE = 'SE203';
    END IF;
    RETURN OLD;
  END IF;
  IF NEW.tenant_id IS DISTINCT FROM app.tenant_id() THEN
    RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF TG_OP = 'INSERT' THEN
    -- The table's own checks then hold a draft to no number, no journal and nobody having posted it.
    IF NEW.status <> 'draft' THEN
      RAISE EXCEPTION 'a stock document starts as a draft' USING ERRCODE = 'SE201';
    END IF;
    NEW.created_at := now();
    NEW.updated_at := clock_timestamp();
    RETURN NEW;
  END IF;
  IF OLD.status = 'posted' THEN
    RAISE EXCEPTION 'a posted stock document is never changed; post an opposite one instead' USING ERRCODE = 'SE203';
  END IF;
  IF NEW.id <> OLD.id OR NEW.tenant_id <> OLD.tenant_id OR NEW.created_by <> OLD.created_by OR NEW.created_at <> OLD.created_at THEN
    RAISE EXCEPTION 'what a stock document is and who wrote it never change' USING ERRCODE = 'SE203';
  END IF;
  -- Always later than what anyone read before this change, so a screen opened earlier can tell.
  NEW.updated_at := clock_timestamp();
  RETURN NEW;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_stock_document() FROM PUBLIC;
--> statement-breakpoint
