-- ── hand-written: what goods coming in are worth when no cost is stated ─────────────────────────
-- Not for the app to call. Goods found (a count that comes out over, an adjustment up with no
-- cost on its line) come in at the cost the warehouse already holds the item at: its
-- weighted-average cost, so the average does not move. A warehouse that holds none (or holds a
-- remnant worth less than a rupee, too little to read a cost from) takes what one cost the
-- last time the item came into it in a quantity worth reading. Not what the last one to leave was worth: the very last of a stock takes whatever
-- rounding left, which can be nothing or too much. Where there is no such cost, or it is
-- nothing, the goods are refused (SE205) and not let in for free: they are brought in by an
-- adjustment that states their cost, be it nothing. The balance row is held until the
-- transaction ends.
CREATE FUNCTION app.stock_gain_value(p_tenant uuid, p_item uuid, p_warehouse uuid, p_quantity numeric) RETURNS numeric
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_quantity numeric;
  v_value numeric;
  v_unit numeric;
  v_code text;
BEGIN
  SELECT b.quantity, b.value INTO v_quantity, v_value FROM public.stock_balances b
    WHERE b.tenant_id = p_tenant AND b.item_id = p_item AND b.warehouse_id = p_warehouse
    FOR UPDATE;
  -- A value is kept to the paisa. Stock worth less than one rupee in all (a sliver of a unit)
  -- is too little to read a cost from: half a paisa of rounding can double it or halve it.
  IF FOUND AND v_quantity > 0 AND v_value >= 1 THEN
    RETURN round(v_value * p_quantity / v_quantity, 2);
  END IF;
  -- The latest move into this warehouse worth a rupee or more: its value over its quantity is
  -- what one cost then. Moves written by one transaction carry one time; between those the
  -- choice is arbitrary, and each is a cost the item really came in at.
  SELECT m.value / m.quantity INTO v_unit FROM public.stock_moves m
    WHERE m.tenant_id = p_tenant AND m.item_id = p_item AND m.warehouse_id = p_warehouse AND m.quantity > 0 AND m.value >= 1
    ORDER BY m.created_at DESC, m.posted_txid DESC, m.id DESC
    LIMIT 1;
  IF v_unit IS NULL OR v_unit <= 0 THEN
    SELECT i.code INTO v_code FROM public.items i WHERE i.tenant_id = p_tenant AND i.id = p_item;
    RAISE EXCEPTION 'no cost is known for % in this warehouse; bring it in with an adjustment that states its cost', v_code USING ERRCODE = 'SE205';
  END IF;
  RETURN round(v_unit * p_quantity, 2);
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.stock_gain_value(uuid, uuid, uuid, numeric) FROM PUBLIC;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.stock_gain_value(uuid, uuid, uuid, numeric) FROM app_runtime, anon, authenticated, service_role;
--> statement-breakpoint

-- ── hand-written: posting a stock transfer ──────────────────────────────────────────────────────
-- One act of the database, whole or not at all: the transfer takes its number, each line
-- leaves the first warehouse at that warehouse's weighted-average cost and arrives in the
-- second worth exactly what it left at. The value of the branch's stock does not change, so
-- there is no journal. Refused: more than the first warehouse holds (SE060), a date in a
-- period that is closed (SE001, SE002) or before the books opened (SE015), and for now two
-- warehouses that belong to different branches (SE208).
--
-- The owner, an accountant and the warehouse post a transfer; a member limited to some
-- branches only between warehouses of those branches.
CREATE FUNCTION app.post_stock_transfer(p_transfer uuid) RETURNS text
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_user uuid := app.current_user_id();
  v_role public.member_role := app.tenant_role();
  v_scope uuid[] := app.tenant_branch_ids();
  v_doc public.stock_transfers%ROWTYPE;
  v_line record;
  v_value numeric;
  v_lines integer := 0;
  v_number text;
BEGIN
  IF v_tenant IS NULL OR v_user IS NULL OR v_role IS NULL OR v_role NOT IN ('owner', 'accountant', 'warehouse_manager') THEN
    RAISE EXCEPTION 'this role cannot post a stock transfer' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'stock documents are posted in read committed transactions' USING ERRCODE = 'SE207';
  END IF;
  SELECT d.* INTO v_doc FROM public.stock_transfers d
    WHERE d.tenant_id = v_tenant AND d.id = p_transfer
    FOR UPDATE;
  -- A transfer that touches a warehouse outside a member's branches does not exist for that member.
  IF NOT FOUND OR (v_scope IS NOT NULL AND EXISTS (
       SELECT 1 FROM public.warehouses w
       WHERE w.tenant_id = v_tenant AND w.id IN (v_doc.from_warehouse_id, v_doc.to_warehouse_id) AND NOT (w.branch_id = ANY (v_scope)))) THEN
    RAISE EXCEPTION 'no such stock transfer in this company' USING ERRCODE = 'SE200';
  END IF;
  IF v_doc.status <> 'draft' THEN
    RAISE EXCEPTION 'only a draft stock transfer is posted' USING ERRCODE = 'SE201';
  END IF;
  -- Each branch's books show its own stock, and a journal belongs to one branch. Goods moved
  -- between branches need an entry in each branch's books, through an account that stands
  -- between the two, and that is not built yet. Until it is, a transfer stays inside one
  -- branch, so that no branch's stock account drifts away from the stock it holds.
  IF (SELECT count(DISTINCT w.branch_id) FROM public.warehouses w
      WHERE w.tenant_id = v_tenant AND w.id IN (v_doc.from_warehouse_id, v_doc.to_warehouse_id)) <> 1 THEN
    RAISE EXCEPTION 'a transfer between the warehouses of two branches is not available yet' USING ERRCODE = 'SE208';
  END IF;
  PERFORM app.require_open_period(v_tenant, v_doc.transfer_date);

  -- Every balance this transfer touches is held first, item by item and warehouse by
  -- warehouse, the same way round for every document, so two never wait on each other.
  INSERT INTO public.stock_balances (tenant_id, item_id, warehouse_id)
    SELECT v_tenant, l.item_id, w.id
    FROM public.stock_transfer_lines l
    CROSS JOIN (VALUES (v_doc.from_warehouse_id), (v_doc.to_warehouse_id)) AS w(id)
    WHERE l.tenant_id = v_tenant AND l.transfer_id = v_doc.id
    ORDER BY l.item_id, w.id
    ON CONFLICT (tenant_id, item_id, warehouse_id) DO NOTHING;
  PERFORM 1 FROM public.stock_balances b
    WHERE b.tenant_id = v_tenant AND b.warehouse_id IN (v_doc.from_warehouse_id, v_doc.to_warehouse_id)
      AND b.item_id IN (SELECT l.item_id FROM public.stock_transfer_lines l WHERE l.tenant_id = v_tenant AND l.transfer_id = v_doc.id)
    ORDER BY b.item_id, b.warehouse_id
    FOR UPDATE;

  v_number := app.next_document_number('ST', v_doc.transfer_date);
  FOR v_line IN
    SELECT l.id, l.item_id, l.quantity FROM public.stock_transfer_lines l
    WHERE l.tenant_id = v_tenant AND l.transfer_id = v_doc.id
    ORDER BY l.item_id
  LOOP
    v_value := app.move_stock(v_tenant, v_user, v_line.item_id, v_doc.from_warehouse_id, v_doc.transfer_date, -v_line.quantity, NULL, 'stock_transfer', v_doc.id, v_line.id);
    PERFORM app.move_stock(v_tenant, v_user, v_line.item_id, v_doc.to_warehouse_id, v_doc.transfer_date, v_line.quantity, v_value, 'stock_transfer', v_doc.id, v_line.id);
    v_lines := v_lines + 1;
  END LOOP;
  IF v_lines = 0 THEN
    RAISE EXCEPTION 'a stock transfer needs at least one line' USING ERRCODE = 'SE202';
  END IF;

  UPDATE public.stock_transfers d SET status = 'posted', number = v_number, posted_at = now(), posted_by = v_user, updated_by = v_user
    WHERE d.tenant_id = v_tenant AND d.id = v_doc.id;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_user, v_role, 'stock_transfer.post', 'stock_transfer', v_doc.id,
      jsonb_build_object('number', v_number, 'date', v_doc.transfer_date, 'lines', v_lines,
        'from', (SELECT w.name FROM public.warehouses w WHERE w.tenant_id = v_tenant AND w.id = v_doc.from_warehouse_id),
        'to', (SELECT w.name FROM public.warehouses w WHERE w.tenant_id = v_tenant AND w.id = v_doc.to_warehouse_id)));
  RETURN v_number;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.post_stock_transfer(uuid) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.post_stock_transfer(uuid) TO app_runtime;
--> statement-breakpoint

-- ── hand-written: the journal of an adjustment or a count ───────────────────────────────────────
-- Not for the app to call. Writes the one journal of a document that changed what stock is
-- worth: goods added are a debit to stock and a credit to the other account; goods taken out
-- the opposite. Both pairs are written when both happened, so the ledger of the other account
-- shows what was added and what was lost, not only the difference. Returns no journal when
-- nothing of value moved.
CREATE FUNCTION app.post_stock_journal(
  p_tenant uuid, p_user uuid, p_role public.member_role, p_date date, p_source_type text, p_source_id uuid,
  p_number text, p_memo text, p_branch uuid, p_contra text, p_value_in numeric, p_value_out numeric
) RETURNS uuid
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_inventory uuid;
  v_contra uuid;
  v_journal uuid;
  v_lines integer := 0;
BEGIN
  IF p_value_in <= 0 AND p_value_out <= 0 THEN
    RETURN NULL;
  END IF;
  v_inventory := app.control_account(p_tenant, 'inventory');
  v_contra := app.control_account(p_tenant, p_contra);
  -- The balance, and the document behind the journal, are asked when the transaction ends, whatever the caller set before this.
  SET CONSTRAINTS public.journals_balanced, public.journal_lines_balanced, public.journals_with_document DEFERRED;
  INSERT INTO public.journals (tenant_id, journal_date, source_type, source_id, document_number, memo, branch_id, created_by)
    VALUES (p_tenant, p_date, p_source_type, p_source_id, p_number, left(p_memo, 500), p_branch, p_user)
    RETURNING id INTO v_journal;
  IF p_value_in > 0 THEN
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
      VALUES (p_tenant, v_journal, v_lines + 1, v_inventory, p_value_in, 0, 'Goods added to stock'),
             (p_tenant, v_journal, v_lines + 2, v_contra, 0, p_value_in, 'Goods added to stock');
    v_lines := v_lines + 2;
  END IF;
  IF p_value_out > 0 THEN
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
      VALUES (p_tenant, v_journal, v_lines + 1, v_contra, p_value_out, 0, 'Goods taken out of stock'),
             (p_tenant, v_journal, v_lines + 2, v_inventory, 0, p_value_out, 'Goods taken out of stock');
    v_lines := v_lines + 2;
  END IF;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (p_tenant, p_user, p_role, 'journal.post', 'journal', v_journal,
      jsonb_build_object('date', p_date, 'source', p_source_type, 'sourceId', p_source_id, 'number', p_number, 'lines', v_lines,
        'total', (greatest(p_value_in, 0) + greatest(p_value_out, 0))::text));
  RETURN v_journal;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.post_stock_journal(uuid, uuid, public.member_role, date, text, uuid, text, text, uuid, text, numeric, numeric) FROM PUBLIC;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.post_stock_journal(uuid, uuid, public.member_role, date, text, uuid, text, text, uuid, text, numeric, numeric) FROM app_runtime, anon, authenticated, service_role;
--> statement-breakpoint

-- ── hand-written: posting a stock adjustment, or opening stock ──────────────────────────────────
-- One act of the database, whole or not at all: the adjustment takes its number; each line
-- below zero leaves stock at the weighted-average cost; each line above zero comes in at the
-- cost stated on it or, with none stated, at the cost the warehouse holds the item at
-- (app.stock_gain_value); and the journal is posted: stock against the stock adjustments
-- account, or against opening balance equity for opening stock. Every line of opening stock
-- that brings goods in states its cost.
--
-- Only the owner and an accountant post one (the founder's decision, 2026-11-14). Refused:
-- more taken out than the warehouse holds (SE060), no cost to go by (SE205), a date in a
-- period that is closed (SE001, SE002) or before the books opened (SE015).
CREATE FUNCTION app.post_stock_adjustment(p_adjustment uuid) RETURNS text
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_user uuid := app.current_user_id();
  v_role public.member_role := app.tenant_role();
  v_scope uuid[] := app.tenant_branch_ids();
  v_doc public.stock_adjustments%ROWTYPE;
  v_branch uuid;
  v_warehouse text;
  v_line record;
  v_code text;
  v_opened date;
  v_value numeric;
  v_in numeric := 0;
  v_out numeric := 0;
  v_lines integer := 0;
  v_number text;
  v_journal uuid;
BEGIN
  IF v_tenant IS NULL OR v_user IS NULL OR v_role IS NULL OR v_role NOT IN ('owner', 'accountant') THEN
    RAISE EXCEPTION 'this role cannot post a stock adjustment' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'stock documents are posted in read committed transactions' USING ERRCODE = 'SE207';
  END IF;
  SELECT d.* INTO v_doc FROM public.stock_adjustments d
    WHERE d.tenant_id = v_tenant AND d.id = p_adjustment
    FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no such stock adjustment in this company' USING ERRCODE = 'SE200';
  END IF;
  SELECT w.branch_id, w.name INTO v_branch, v_warehouse FROM public.warehouses w WHERE w.tenant_id = v_tenant AND w.id = v_doc.warehouse_id;
  IF v_scope IS NOT NULL AND NOT (v_branch = ANY (v_scope)) THEN
    RAISE EXCEPTION 'no such stock adjustment in this company' USING ERRCODE = 'SE200';
  END IF;
  IF v_doc.status <> 'draft' THEN
    RAISE EXCEPTION 'only a draft stock adjustment is posted' USING ERRCODE = 'SE201';
  END IF;
  IF v_doc.kind = 'opening' THEN
    SELECT i.code INTO v_code
      FROM public.stock_adjustment_lines l
      JOIN public.items i ON i.tenant_id = l.tenant_id AND i.id = l.item_id
      WHERE l.tenant_id = v_tenant AND l.adjustment_id = v_doc.id AND l.quantity > 0 AND l.unit_cost IS NULL
      ORDER BY l.line_no
      LIMIT 1;
    IF FOUND THEN
      RAISE EXCEPTION 'opening stock of % needs what one cost', v_code USING ERRCODE = 'SE205';
    END IF;
    -- Opening stock goes to opening balance equity, past the profit and loss account, so it
    -- belongs to the day the books opened here and to no other. Once the company's opening
    -- balances are posted, opening stock is dated on their date.
    SELECT e.opening_date INTO v_opened FROM public.opening_entries e WHERE e.tenant_id = v_tenant AND e.status = 'posted';
    IF v_opened IS NOT NULL AND v_doc.adjustment_date <> v_opened THEN
      RAISE EXCEPTION 'the books were opened on %; opening stock is dated on that day', v_opened USING ERRCODE = 'SE210';
    END IF;
  END IF;
  PERFORM app.require_open_period(v_tenant, v_doc.adjustment_date);

  -- Every balance this adjustment touches is held first, item by item, as for every document.
  INSERT INTO public.stock_balances (tenant_id, item_id, warehouse_id)
    SELECT v_tenant, l.item_id, v_doc.warehouse_id
    FROM public.stock_adjustment_lines l
    WHERE l.tenant_id = v_tenant AND l.adjustment_id = v_doc.id
    ORDER BY l.item_id
    ON CONFLICT (tenant_id, item_id, warehouse_id) DO NOTHING;
  PERFORM 1 FROM public.stock_balances b
    WHERE b.tenant_id = v_tenant AND b.warehouse_id = v_doc.warehouse_id
      AND b.item_id IN (SELECT l.item_id FROM public.stock_adjustment_lines l WHERE l.tenant_id = v_tenant AND l.adjustment_id = v_doc.id)
    ORDER BY b.item_id
    FOR UPDATE;

  v_number := app.next_document_number('SA', v_doc.adjustment_date);
  FOR v_line IN
    SELECT l.id, l.item_id, l.quantity, l.unit_cost FROM public.stock_adjustment_lines l
    WHERE l.tenant_id = v_tenant AND l.adjustment_id = v_doc.id
    ORDER BY l.item_id
  LOOP
    IF v_line.quantity < 0 THEN
      v_out := v_out + app.move_stock(v_tenant, v_user, v_line.item_id, v_doc.warehouse_id, v_doc.adjustment_date, v_line.quantity, NULL, 'stock_adjustment', v_doc.id, v_line.id);
    ELSE
      IF v_line.unit_cost IS NOT NULL THEN
        v_value := round(v_line.quantity * v_line.unit_cost, 2);
      ELSE
        v_value := app.stock_gain_value(v_tenant, v_line.item_id, v_doc.warehouse_id, v_line.quantity);
      END IF;
      PERFORM app.move_stock(v_tenant, v_user, v_line.item_id, v_doc.warehouse_id, v_doc.adjustment_date, v_line.quantity, v_value, 'stock_adjustment', v_doc.id, v_line.id);
      v_in := v_in + v_value;
    END IF;
    v_lines := v_lines + 1;
  END LOOP;
  IF v_lines = 0 THEN
    RAISE EXCEPTION 'a stock adjustment needs at least one line' USING ERRCODE = 'SE202';
  END IF;

  v_journal := app.post_stock_journal(v_tenant, v_user, v_role, v_doc.adjustment_date, 'stock_adjustment', v_doc.id, v_number,
    CASE v_doc.kind WHEN 'opening' THEN 'Opening stock in ' || v_warehouse ELSE 'Stock adjustment in ' || v_warehouse || ': ' || replace(v_doc.reason, '_', ' ') || coalesce(', ' || btrim(v_doc.note), '') END,
    v_branch, CASE v_doc.kind WHEN 'opening' THEN 'opening_equity' ELSE 'stock_adjustment' END, v_in, v_out);
  UPDATE public.stock_adjustments d SET status = 'posted', number = v_number, journal_id = v_journal, posted_at = now(), posted_by = v_user, updated_by = v_user
    WHERE d.tenant_id = v_tenant AND d.id = v_doc.id;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_user, v_role, 'stock_adjustment.post', 'stock_adjustment', v_doc.id,
      jsonb_build_object('number', v_number, 'kind', v_doc.kind, 'date', v_doc.adjustment_date, 'warehouse', v_warehouse, 'reason', v_doc.reason, 'lines', v_lines,
        'added', v_in::text, 'takenOut', v_out::text, 'journalId', v_journal));
  RETURN v_number;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.post_stock_adjustment(uuid) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.post_stock_adjustment(uuid) TO app_runtime;
--> statement-breakpoint

-- ── hand-written: a stock count, from finished to posted ────────────────────────────────────────
-- The count's row, held for the rest of the transaction, for a member who may work on it;
-- to anyone else it does not exist. Not for the app to call.
CREATE FUNCTION app.hold_stock_count(p_count uuid, p_roles public.member_role[]) RETURNS public.stock_counts
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_role public.member_role := app.tenant_role();
  v_scope uuid[] := app.tenant_branch_ids();
  v_doc public.stock_counts%ROWTYPE;
BEGIN
  IF v_tenant IS NULL OR app.current_user_id() IS NULL OR v_role IS NULL OR NOT (v_role = ANY (p_roles)) THEN
    RAISE EXCEPTION 'this role cannot do that to a stock count' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'stock documents are posted in read committed transactions' USING ERRCODE = 'SE207';
  END IF;
  SELECT d.* INTO v_doc FROM public.stock_counts d
    WHERE d.tenant_id = v_tenant AND d.id = p_count
    FOR UPDATE;
  IF NOT FOUND OR (v_scope IS NOT NULL AND NOT EXISTS (
       SELECT 1 FROM public.warehouses w WHERE w.tenant_id = v_tenant AND w.id = v_doc.warehouse_id AND w.branch_id = ANY (v_scope))) THEN
    RAISE EXCEPTION 'no such stock count in this company' USING ERRCODE = 'SE200';
  END IF;
  RETURN v_doc;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.hold_stock_count(uuid, public.member_role[]) FROM PUBLIC;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.hold_stock_count(uuid, public.member_role[]) FROM app_runtime, anon, authenticated, service_role;
--> statement-breakpoint

-- Finished counting: the sheet is closed to changes and waits for an owner or an accountant.
-- The owner, an accountant or the warehouse marks it so, once something has been counted.
CREATE FUNCTION app.submit_stock_count(p_count uuid) RETURNS void
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_doc public.stock_counts%ROWTYPE := app.hold_stock_count(p_count, ARRAY['owner', 'accountant', 'warehouse_manager']::public.member_role[]);
  v_user uuid := app.current_user_id();
  v_counted integer;
  v_left integer;
BEGIN
  IF v_doc.status <> 'draft' THEN
    RAISE EXCEPTION 'only a count that is still being counted is marked finished' USING ERRCODE = 'SE201';
  END IF;
  SELECT count(l.counted_quantity), count(*) - count(l.counted_quantity) INTO v_counted, v_left
    FROM public.stock_count_lines l WHERE l.tenant_id = v_doc.tenant_id AND l.count_id = v_doc.id;
  IF v_counted = 0 THEN
    RAISE EXCEPTION 'nothing has been counted yet' USING ERRCODE = 'SE202';
  END IF;
  UPDATE public.stock_counts d SET status = 'submitted', submitted_at = now(), submitted_by = v_user, updated_by = v_user
    WHERE d.tenant_id = v_doc.tenant_id AND d.id = v_doc.id;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, before, after)
    VALUES (v_doc.tenant_id, v_user, app.tenant_role(), 'stock_count.submit', 'stock_count', v_doc.id,
      jsonb_build_object('status', 'draft'), jsonb_build_object('status', 'submitted', 'date', v_doc.count_date, 'counted', v_counted, 'notCounted', v_left));
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.submit_stock_count(uuid) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.submit_stock_count(uuid) TO app_runtime;
--> statement-breakpoint

-- Sent back, or taken back: the sheet can be changed again.
CREATE FUNCTION app.return_stock_count(p_count uuid) RETURNS void
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_doc public.stock_counts%ROWTYPE := app.hold_stock_count(p_count, ARRAY['owner', 'accountant', 'warehouse_manager']::public.member_role[]);
  v_user uuid := app.current_user_id();
BEGIN
  IF v_doc.status <> 'submitted' THEN
    RAISE EXCEPTION 'only a finished count that is not yet posted is sent back' USING ERRCODE = 'SE201';
  END IF;
  UPDATE public.stock_counts d SET status = 'draft', submitted_at = NULL, submitted_by = NULL, updated_by = v_user
    WHERE d.tenant_id = v_doc.tenant_id AND d.id = v_doc.id;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, before, after)
    VALUES (v_doc.tenant_id, v_user, app.tenant_role(), 'stock_count.return', 'stock_count', v_doc.id,
      jsonb_build_object('status', 'submitted'), jsonb_build_object('status', 'draft'));
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.return_stock_count(uuid) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.return_stock_count(uuid) TO app_runtime;
--> statement-breakpoint

-- Brings every line's "what the books held" up to this moment, on a sheet still being counted:
-- for a count that was made after stock moved. A line whose figure changes loses what was
-- counted on it and is counted again: a count taken against the old figure, kept beside the
-- new one, would show a difference that nobody found on the shelf. Returns how many lines
-- changed.
CREATE FUNCTION app.rebook_stock_count(p_count uuid) RETURNS integer
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_doc public.stock_counts%ROWTYPE := app.hold_stock_count(p_count, ARRAY['owner', 'accountant', 'warehouse_manager']::public.member_role[]);
  v_user uuid := app.current_user_id();
  v_changed integer;
BEGIN
  IF v_doc.status <> 'draft' THEN
    RAISE EXCEPTION 'only a count that is still being counted is brought up to date' USING ERRCODE = 'SE201';
  END IF;
  WITH held AS (
    SELECT l.id, coalesce(b.quantity, 0) AS quantity
    FROM public.stock_count_lines l
    LEFT JOIN public.stock_balances b ON b.tenant_id = l.tenant_id AND b.item_id = l.item_id AND b.warehouse_id = v_doc.warehouse_id
    WHERE l.tenant_id = v_doc.tenant_id AND l.count_id = v_doc.id
  ), changed AS (
    UPDATE public.stock_count_lines l SET book_quantity = held.quantity, counted_quantity = NULL
      FROM held
      WHERE l.tenant_id = v_doc.tenant_id AND l.id = held.id AND l.book_quantity <> held.quantity
      RETURNING 1
  )
  SELECT count(*) INTO v_changed FROM changed;
  UPDATE public.stock_counts d SET updated_by = v_user WHERE d.tenant_id = v_doc.tenant_id AND d.id = v_doc.id;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_doc.tenant_id, v_user, app.tenant_role(), 'stock_count.rebook', 'stock_count', v_doc.id, jsonb_build_object('linesChanged', v_changed));
  RETURN v_changed;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.rebook_stock_count(uuid) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.rebook_stock_count(uuid) TO app_runtime;
--> statement-breakpoint

-- Posts a finished count: one act of the database, whole or not at all. Every counted line
-- moves stock by the difference between what was counted and what the books held when the
-- line was written: a shortage leaves at the weighted-average cost, a surplus comes in at the
-- cost the warehouse holds the item at (app.stock_gain_value). The value of the differences is
-- posted to the stock adjustments account. Lines not counted are left alone. A count with no
-- differences is posted too, with no moves and no journal: it records that the shelves agreed.
--
-- The difference is applied on top of what the warehouse holds now. That is right when the
-- shelves were counted before any later movement; it is wrong when they were counted after.
-- So when a counted item's stock is no longer what the sheet says the books held, posting is
-- refused (SE206) unless the caller says the count came first (p_accept_moved). Otherwise the
-- sheet is sent back, brought up to date and the items that moved counted again
-- (app.rebook_stock_count).
--
-- Only the owner and an accountant post a count (the founder's decision, 2026-11-14), and they
-- post the sheet they looked at: p_seen is the count's "last changed" as the poster read it.
-- A sheet that was taken back, changed and finished again in the meantime has a later one and
-- is refused (SE209), to be looked at again.
CREATE FUNCTION app.post_stock_count(p_count uuid, p_seen timestamptz, p_accept_moved boolean DEFAULT false) RETURNS text
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_doc public.stock_counts%ROWTYPE := app.hold_stock_count(p_count, ARRAY['owner', 'accountant']::public.member_role[]);
  v_tenant uuid := v_doc.tenant_id;
  v_user uuid := app.current_user_id();
  v_role public.member_role := app.tenant_role();
  v_branch uuid;
  v_warehouse text;
  v_line record;
  v_value numeric;
  v_in numeric := 0;
  v_out numeric := 0;
  v_counted integer;
  v_differences integer := 0;
  v_moved text;
  v_moved_count integer;
  v_number text;
  v_journal uuid;
BEGIN
  IF v_doc.status <> 'submitted' THEN
    RAISE EXCEPTION 'only a finished stock count is posted' USING ERRCODE = 'SE201';
  END IF;
  -- To the millisecond: that is as fine as a screen can carry the time it read.
  IF p_seen IS NULL OR date_trunc('milliseconds', v_doc.updated_at) <> date_trunc('milliseconds', p_seen) THEN
    RAISE EXCEPTION 'this count changed after it was last looked at; look at it again before posting it' USING ERRCODE = 'SE209';
  END IF;
  SELECT w.branch_id, w.name INTO v_branch, v_warehouse FROM public.warehouses w WHERE w.tenant_id = v_tenant AND w.id = v_doc.warehouse_id;
  SELECT count(*) INTO v_counted FROM public.stock_count_lines l
    WHERE l.tenant_id = v_tenant AND l.count_id = v_doc.id AND l.counted_quantity IS NOT NULL;
  IF v_counted = 0 THEN
    RAISE EXCEPTION 'nothing has been counted' USING ERRCODE = 'SE202';
  END IF;
  PERFORM app.require_open_period(v_tenant, v_doc.count_date);

  -- Every balance this count touches is held first, item by item, as for every document.
  INSERT INTO public.stock_balances (tenant_id, item_id, warehouse_id)
    SELECT v_tenant, l.item_id, v_doc.warehouse_id
    FROM public.stock_count_lines l
    WHERE l.tenant_id = v_tenant AND l.count_id = v_doc.id AND l.counted_quantity IS NOT NULL
    ORDER BY l.item_id
    ON CONFLICT (tenant_id, item_id, warehouse_id) DO NOTHING;
  PERFORM 1 FROM public.stock_balances b
    WHERE b.tenant_id = v_tenant AND b.warehouse_id = v_doc.warehouse_id
      AND b.item_id IN (SELECT l.item_id FROM public.stock_count_lines l WHERE l.tenant_id = v_tenant AND l.count_id = v_doc.id AND l.counted_quantity IS NOT NULL)
    ORDER BY b.item_id
    FOR UPDATE;

  -- Stock that is no longer what the sheet says the books held.
  SELECT count(*), string_agg(x.code, ', ' ORDER BY x.code) INTO v_moved_count, v_moved
    FROM (
      SELECT i.code
      FROM public.stock_count_lines l
      JOIN public.items i ON i.tenant_id = l.tenant_id AND i.id = l.item_id
      JOIN public.stock_balances b ON b.tenant_id = l.tenant_id AND b.item_id = l.item_id AND b.warehouse_id = v_doc.warehouse_id
      WHERE l.tenant_id = v_tenant AND l.count_id = v_doc.id AND l.counted_quantity IS NOT NULL AND b.quantity <> l.book_quantity
    ) x;
  IF v_moved_count > 0 AND NOT coalesce(p_accept_moved, false) THEN
    RAISE EXCEPTION 'stock has moved since this sheet was started: %', left(v_moved, 300) USING ERRCODE = 'SE206';
  END IF;

  v_number := app.next_document_number('SC', v_doc.count_date);
  FOR v_line IN
    SELECT l.id, l.item_id, l.counted_quantity - l.book_quantity AS difference FROM public.stock_count_lines l
    WHERE l.tenant_id = v_tenant AND l.count_id = v_doc.id AND l.counted_quantity IS NOT NULL AND l.counted_quantity <> l.book_quantity
    ORDER BY l.item_id
  LOOP
    IF v_line.difference < 0 THEN
      v_out := v_out + app.move_stock(v_tenant, v_user, v_line.item_id, v_doc.warehouse_id, v_doc.count_date, v_line.difference, NULL, 'stock_count', v_doc.id, v_line.id);
    ELSE
      v_value := app.stock_gain_value(v_tenant, v_line.item_id, v_doc.warehouse_id, v_line.difference);
      PERFORM app.move_stock(v_tenant, v_user, v_line.item_id, v_doc.warehouse_id, v_doc.count_date, v_line.difference, v_value, 'stock_count', v_doc.id, v_line.id);
      v_in := v_in + v_value;
    END IF;
    v_differences := v_differences + 1;
  END LOOP;

  v_journal := app.post_stock_journal(v_tenant, v_user, v_role, v_doc.count_date, 'stock_count', v_doc.id, v_number,
    'Stock count of ' || v_warehouse || ': differences', v_branch, 'stock_adjustment', v_in, v_out);
  UPDATE public.stock_counts d SET status = 'posted', number = v_number, journal_id = v_journal, posted_at = now(), posted_by = v_user, updated_by = v_user
    WHERE d.tenant_id = v_tenant AND d.id = v_doc.id;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, before, after)
    VALUES (v_tenant, v_user, v_role, 'stock_count.post', 'stock_count', v_doc.id, jsonb_build_object('status', 'submitted'),
      jsonb_build_object('status', 'posted', 'number', v_number, 'date', v_doc.count_date, 'warehouse', v_warehouse, 'counted', v_counted, 'differences', v_differences,
        'surplus', v_in::text, 'shortage', v_out::text, 'journalId', v_journal, 'movedSince', v_moved));
  RETURN v_number;
END $$;
